import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that utilizes a dynamic bit array
    represented as an integer and uses a unique seed-based hashing
    strategy to minimize space while achieving the desired false 
    positive rate. The design allows for efficient membership testing and
    controlled memory usage through carefully calculated parameters.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the optimal size of the bit array and number of hash functions
        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_hash_count()

        # Initialize the bit array as an integer
        self.bit_array = 0

    def _calculate_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array in bits."""
        return int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash for the item giving a different seed for uniqueness."""
        hash_result = hashlib.md5((item + str(seed)).encode('utf-8')).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.hash_count):
            index = self._hash(item, i)
            self.bit_array |= (1 << index)  # Set the bit at position 'index'

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all((self.bit_array & (1 << self._hash(item, i))) != 0 for i in range(self.hash_count))

