class BloomFilter:
    """
    A Bloom Filter implementation that uses a custom approach to
    manage the bit array via a list of integers and employs a
    unique combined hash method to enhance efficiency. The size 
    of the bit array and the number of hash functions are derived 
    from the expected items and false positive rate while focusing 
    on ensuring low memory usage and quick access.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Compute optimal bit array size and number of hash functions
        self.size = self._optimal_bit_array_size()
        self.hash_count = self._optimal_number_of_hashes()

        # Initialize bit array represented as a list of integers
        self.bit_array = [0] * ((self.size // 32) + 1)

    def _optimal_bit_array_size(self) -> int:
        """Calculate optimal size of the bit array in bits."""
        return int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_number_of_hashes(self) -> int:
        """Calculate optimal number of distinct hash functions."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the item using multiple seeds."""
        hashes = []
        for i in range(self.hash_count):
            combined_hash = hashlib.sha1((item + str(i)).encode('utf-8')).hexdigest()
            hash_index = int(combined_hash, 16) % self.size
            hashes.append(hash_index)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index // 32] |= (1 << (index % 32))

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all((self.bit_array[index // 32] & (1 << (index % 32))) != 0 for index in self._hashes(item))

